entries[16054] = { ["name"] = "Schematic: Arcanite Dragonling", ["text"] = "Requires Engineering (300)\nUse: Teaches you how to make an Arcanite Dragonling.\nArcanite Dragonling\nBinds when equipped\nUnique\nTrinket\nRequires Level 50\nRequires Engineering (300)\nUse: Activates your Arcanite Dragonling to fight for you for 1 min. It requires an hour to cool down before it can be used again. (1 Hour Cooldown)\nRequires Mithril Mechanical Dragonling , Delicate Arcanite Converter (8), Enchanted Thorium Bar (10), Thorium Widget (6), Gold Power Core (4), Enchanted Leather (6)" }
entries[16055] = { ["name"] = "Schematic: Arcane Bomb", ["text"] = "Requires Engineering (300)\nUse: Teaches you how to make an Arcane Bomb.\nArcane Bomb\nRequires Engineering (300)\nUse: Drains 675 to 1125 mana from those in the blast radius and does 50% of the mana drained in damage to the target. Also Silences targets in the blast for 5 sec. (1 Min Cooldown)\nRequires Delicate Arcanite Converter , Thorium Bar (3), Runecloth" }
entries[16056] = { ["name"] = "Schematic: Flawless Arcanite Rifle", ["text"] = "Requires Engineering (300)\nUse: Teaches you how to make a Flawless Arcanite Rifle.\nFlawless Arcanite Rifle\nBinds when equipped\nRanged Gun\n65 - 122 Damage Speed 3.00\n(31.17 damage per second)\nDurability 75 / 75\nRequires Level 56\nEquip: Increased Guns +4.\nEquip: +10 ranged Attack Power.\nRequires Arcanite Bar (10), Thorium Tube (2), Essence of Fire (2), Essence of Earth (2), Azerothian Diamond (2), Enchanted Leather (2)" }
