entries[17564] = { ["name"] = "Knight-Lieutenant's Dreadweave Gloves", ["text"] = "Binds when picked up\nUnique\nHands Cloth\n56 Armor\n+18 Stamina\n+11 Intellect\nDurability 30 / 30\nClasses: Warlock\nRequires Level 58\nEquip: Gives you a 50% chance to avoid interruption caused by damage while casting Searing Pain.\n\nLieutenant Commander's Threads (0/6)\nKnight-Lieutenant's Dreadweave Boots\nKnight-Lieutenant's Dreadweave Gloves\nKnight-Captain's Dreadweave Robe\nKnight-Captain's Dreadweave Leggings\nLieutenant Commander's Dreadweave Mantle\nLieutenant Commander's Headguard\n(2) Set : Increases damage and healing done by magical spells and effects by up to 23.\n(4) Set : Reduces the casting time of your Immolate spell by 0.2 sec.\n(6) Set : +15 Stamina." }
